                    console.log(`您点击了功能卡片: ${title}`);
                    // 可以在这里添加更复杂的交互，比如显示详情模态框
                });
            });

            // 4. 音频/视频播放状态日志（用于演示）
            const audioPlayer = document.getElementById('media_audio_track');
            const videoPlayer = document.getElementById('media_video_video');

            if(audioPlayer) {
                audioPlayer.addEventListener('play', () => console.log('音频开始播放'));
                audioPlayer.addEventListener('pause', () => console.log('音频暂停'));
            }

            if(videoPlayer) {
                videoPlayer.addEventListener('play', () => console.log('视频开始播放'));
                videoPlayer.addEventListener('pause', () => console.log('视频暂停'));
            }
        });
    </script>
